Outcome Rules::repair(Sender sender,const Value&m){using namespace rule;require(!sender.worker&&accepting(),"inactive repair owner");auto*actor=state_.actor("player",sender.id);require(actor&&alive(*actor)&&actor->get("participating").truth(true),"inactive repair player");const auto base=rule::integer(m.get("critical_base_revision"),0,INT32_MAX),seq=rule::integer(m.get("repair_seq"),1,INT32_MAX);require(base==intField(*actor,"critical_base_revision"),"stale repair lineage");const auto&tracks=m.get("tracks");require(isArray(tracks)&&!rows(tracks).empty()&&rows(tracks).size()<=2,"invalid tracks");Value fingerprint=tracks;for(auto&r:fingerprint.array){r.object["hp"]=number(rounded(r.get("hp").numeric(),3));r.object["max_hp"]=number(rounded(r.get("max_hp").numeric(),3));}std::sort(fingerprint.array.begin(),fingerprint.array.end(),[](const Value&a,const Value&b){return field(a,"name")<field(b,"name");});Value candidate=actor->get("critical");std::set<std::string> seen;bool improved=false;std::size_t converged=0;auto destroyed=strings(candidate.get("destroyed"));for(const auto&r:rows(tracks)){shape(r,{"name","hp","max_hp","state"});const auto name=field(r,"name"),state=field(r,"state");require((name=="leftTrackHealth"||name=="rightTrackHealth")&&seen.insert(name).second&&(state=="destroyed"||state=="critical"),"invalid track row");const auto max=scalar(r.get("max_hp"),.000001,1e9),hp=scalar(r.get("hp"),0.,max);auto&ds=candidate.object["devices"].array;auto old=std::find_if(ds.begin(),ds.end(),[&](const auto&d){return field(d,"name")==name;});require(old!=ds.end(),"track missing");if(seq<=intField(*actor,"critical_ack_seq"))continue;if(field(*old,"state")!="destroyed"&&!destroyed.count(name)){++converged;continue;}require(field(*old,"state")=="destroyed"&&destroyed.count(name)&&std::abs(old->get("max_hp").numeric()-max)<=.001&&hp+.001>=old->get("hp").numeric(),"nonmonotone track repair");improved=improved||hp>old->get("hp").numeric()+.001||state=="critical";*old=r;if(state=="critical")destroyed.erase(name);}
 if(seq<=intField(*actor,"critical_ack_seq")){const auto&history=repair_requests_[sender.id];const auto prior=history.find(seq);return prior==history.end()||prior->second==fingerprint?Outcome::accept():Outcome::reject("conflicting_retry");}require(improved||converged==rows(tracks).size(),"no repair progress");candidate.object["destroyed"]=strings(destroyed);candidate=canonicalCritical(candidate);const auto revision=intField(*actor,"critical_revision");commitCritical(*actor,candidate,{},false);if(intField(*actor,"critical_revision")==revision)add(*actor,"critical_revision",1);actor->object["critical_ack_seq"]=integer(seq);auto&history=repair_requests_[sender.id];history[seq]=fingerprint;while(history.size()>64)history.erase(history.begin());return Outcome::accept();}
